// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    function setUp() public { c = new MyContract(); }
    function testFuzz_property(uint128 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(uint160(receiver) > 0x0A); // exclude precompiles, which reject transfers
        vm.assume(receiver != address(c));
        uint256 amt = uint256(bound(uint256(amount), 1, type(uint128).max));
        vm.deal(address(c), amt);
        uint256 before = address(c).balance;
        bool ok;
        try c.sendTo(receiver, amt) { ok = true; } catch { ok = false; }
        assertTrue(ok && address(c).balance == before - amt);
    }
}
